acceptance_cmd:
set -x; out="$(./ops/docs_impact.py --files devops.sh)" || { echo "FAIL: docs_impact.py did not run"; exit 3; }
printf "%s\n" "${out}" | grep -q "^IMPACT runbook\.system docs/runbook/system\.md " || { echo "FAIL positive-control: registry no longer declares devops.sh (renamed-and-mirrored / parse broken / wrong repo) -- not this defect"; exit 4; }
printf "%s\n" "${out}" | grep -q "^IMPACT sop\.backup docs/sop/backup\.md " || { echo "RED: docs_impact does not nominate docs/sop/backup.md when devops.sh changes"; exit 1; }
printf "%s\n" "${out}" | grep -q "^IMPACT sop\.backup_restore docs/sop/backup_restore\.md " || { echo "RED: docs_impact does not nominate docs/sop/backup_restore.md when devops.sh changes"; exit 1; }
grep -qE "^[^#]*docs_impact\.py --files devops\.sh" ops/tests/test_docs_impact.sh || { echo "RED: no regression test drives devops.sh through docs_impact -- the declaration is unguarded and can silently regress"; exit 1; }
bash ops/tests/test_docs_impact.sh >/dev/null 2>&1 || { echo "FAIL: ops/tests/test_docs_impact.sh is red -- docs impact suite broken, not necessarily this defect"; exit 6; }
echo "OK: devops.sh nominates sop.backup + sop.backup_restore; pinned by test_docs_impact.sh; suite green; positive control runbook.system present"
